import{_ as a,o as d,c as n,ae as e}from"./chunks/framework.CJnqVqMy.js";const c=JSON.parse('{"title":"演进趋势","description":"","frontmatter":{},"headers":[],"relativePath":"trends.md","filePath":"trends.md"}'),s={name:"trends.md"};function o(r,t,p,l,h,u){return d(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="演进趋势" tabindex="-1">演进趋势 <a class="header-anchor" href="#演进趋势" aria-label="Permalink to &quot;演进趋势&quot;">​</a></h1><p>从 2018 年 GLUE 开创多任务评估范式至今，AI 评测基准经历了多轮范式变迁。以下是从 36 个基准中提炼出的 5 条核心趋势。</p><h2 id="从-能不能-到-好不好-再到-值不值" tabindex="-1">从&quot;能不能&quot;到&quot;好不好&quot;再到&quot;值不值&quot; <a class="header-anchor" href="#从-能不能-到-好不好-再到-值不值" aria-label="Permalink to &quot;从&quot;能不能&quot;到&quot;好不好&quot;再到&quot;值不值&quot;&quot;">​</a></h2><p>评测基准所回答的核心问题，随着 AI 能力的提升在不断升级：</p><table tabindex="0"><thead><tr><th>阶段</th><th>时间</th><th>代表基准</th><th>核心问题</th></tr></thead><tbody><tr><td>语言理解</td><td>2018–2019</td><td>GLUE, SuperGLUE, SQuAD 2.0</td><td>模型能否理解语言？</td></tr><tr><td>知识广度</td><td>2020–2022</td><td>MMLU, BIG-bench, HELM</td><td>模型知道多少？</td></tr><tr><td>真实任务</td><td>2023–2024</td><td>SWE-bench, WebArena, Tau-bench</td><td>模型能完成实际工作吗？</td></tr><tr><td>经济价值</td><td>2025</td><td>SWE-Lancer, MLE-bench</td><td>模型能创造多少价值？</td></tr></tbody></table><p>早期基准测试&quot;理解不理解&quot;，很快被刷穿；然后测&quot;知道多少&quot;，MMLU 达到 90+ 后区分度下降；接着转向&quot;能不能干活&quot;，再到现在直接用美元衡量产出——SWE-Lancer 用 Upwork 真实任务定价，总价值超过 100 万美元。</p><h2 id="基准寿命缩短-军备竞赛-加速" tabindex="-1">基准寿命缩短，&quot;军备竞赛&quot;加速 <a class="header-anchor" href="#基准寿命缩短-军备竞赛-加速" aria-label="Permalink to &quot;基准寿命缩短，&quot;军备竞赛&quot;加速&quot;">​</a></h2><p>评测基准的&quot;有效寿命&quot;正在急剧缩短：</p><table tabindex="0"><thead><tr><th>基准</th><th>发布</th><th>被实质性超越</th><th>存活周期</th></tr></thead><tbody><tr><td>GLUE</td><td>2018</td><td>~2019</td><td>~1 年</td></tr><tr><td>SuperGLUE</td><td>2019</td><td>~2021</td><td>~2 年</td></tr><tr><td>GSM8K</td><td>2021</td><td>~2024（主流模型接近满分）</td><td>~3 年</td></tr><tr><td>ARC-AGI</td><td>2024</td><td>2025（推出 ARC-AGI-2）</td><td>&lt; 1 年</td></tr></tbody></table><blockquote><p>好的基准不是模型能考高分的，而是能暴露模型不能做什么的。</p></blockquote><p>社区已经开始用新策略对抗这种&quot;基准失效&quot;：</p><ul><li><strong>动态题库</strong> —— LiveBench 每月更新题目，从根源上抵抗数据污染</li><li><strong>真人对抗</strong> —— Chatbot Arena 通过持续的人类盲评投票，构建不会过期的 Elo 排名</li><li><strong>极限难度</strong> —— FrontierMath（最强模型 &lt; 2%）、Humanity&#39;s Last Exam（最强模型 ~10%）</li></ul><h2 id="评测维度从单一走向分化" tabindex="-1">评测维度从单一走向分化 <a class="header-anchor" href="#评测维度从单一走向分化" aria-label="Permalink to &quot;评测维度从单一走向分化&quot;">​</a></h2><p>2018 年只有&quot;通用能力&quot;一个赛道，到 2025 年已裂变为 8 个独立方向：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2018  通用能力 ────────────────────────────</span></span>
<span class="line"><span>2021  ├── 推理与数学 (MATH, GSM8K)</span></span>
<span class="line"><span>      ├── 代码能力 (HumanEval, MBPP)</span></span>
<span class="line"><span>      └── 安全与对齐 (TruthfulQA)</span></span>
<span class="line"><span>2023  ├── Agent 能力 (AgentBench, WebArena, GAIA)</span></span>
<span class="line"><span>      ├── 对话与偏好 (Chatbot Arena, AlpacaEval)</span></span>
<span class="line"><span>      ├── 多模态 (MMMU)</span></span>
<span class="line"><span>      └── 中文评测 (C-Eval, CMMLU)</span></span>
<span class="line"><span>2024  ├── 极限推理 (ARC-AGI, FrontierMath)</span></span>
<span class="line"><span>      └── 真实工程 (SWE-bench Verified, Tau-bench)</span></span></code></pre></div><p>这种分化反映了两个现实：AI 应用场景爆发式增长，以及单一基准已无法全面衡量模型能力。2023 年成为关键拐点——这一年同时诞生了 Agent 评测、对话偏好评测、多模态评测和中文专项评测四个新赛道。</p><h2 id="评测方法论的三次范式转移" tabindex="-1">评测方法论的三次范式转移 <a class="header-anchor" href="#评测方法论的三次范式转移" aria-label="Permalink to &quot;评测方法论的三次范式转移&quot;">​</a></h2><p>评测&quot;怎么测&quot;的方式本身也在进化：</p><p><strong>第一范式：静态数据集 + 自动指标（2018–2021）</strong></p><p>固定测试集搭配 F1 / 准确率等指标。优势是可复现，问题是容易被过拟合和数据污染攻破。代表：GLUE、MMLU、HumanEval。</p><p><strong>第二范式：LLM-as-Judge + 人类偏好（2023）</strong></p><p>用 GPT-4 等强模型作为裁判打分，或通过人类盲评投票建立排名。解决了开放式生成&quot;没有标准答案&quot;的评判难题。代表：MT-Bench、AlpacaEval、Chatbot Arena。</p><p><strong>第三范式：真实环境端到端（2024–2025）</strong></p><p>评测在真实 GitHub 仓库跑测试（SWE-bench）、在真实浏览器中操作网页（WebArena）、在真实客服场景中对话（Tau-bench）。评测本身变成了一个工程系统，而非一组题目。</p><h2 id="难度天花板不断被推高" tabindex="-1">难度天花板不断被推高 <a class="header-anchor" href="#难度天花板不断被推高" aria-label="Permalink to &quot;难度天花板不断被推高&quot;">​</a></h2><p>当前最前沿的基准刻意追求&quot;模型做不到&quot;的难度：</p><table tabindex="0"><thead><tr><th>基准</th><th>年份</th><th>顶级模型表现</th><th>人类表现</th></tr></thead><tbody><tr><td>FrontierMath</td><td>2024</td><td>&lt; 2%</td><td>研究级数学家出题</td></tr><tr><td>Humanity&#39;s Last Exam</td><td>2025</td><td>~10%</td><td>全球专家众包</td></tr><tr><td>ARC-AGI-2</td><td>2025</td><td>远低于人类</td><td>人类平均可完成</td></tr><tr><td>GAIA</td><td>2023</td><td>GPT-4 仅 15%</td><td>人类 92%</td></tr></tbody></table><p>这些基准的共同特征：<strong>人类能做到，但 AI 做不到</strong>。它们不再追求学术上的全面覆盖，而是精准地刺向当前 AI 的能力盲区——抽象推理、跨学科综合、多步工具使用。</p><p>这也揭示了一个深层趋势：评测社区的关注点正在从&quot;AI 有多强&quot;转向&quot;AI 与人类的差距还有多大&quot;。</p>`,29)])])}const q=a(s,[["render",o]]);export{c as __pageData,q as default};
